def pair_with_sum(a: list[int], target: int) -> tuple[int, int] | None:
    lo, hi = 0, len(a) - 1               # a must be sorted
    while lo < hi:                       # < not <=: an element can't pair with itself
        s = a[lo] + a[hi]
        if s == target:
            return lo, hi
        if s < target:
            lo += 1                      # a[lo] is too small even with the largest partner
        else:
            hi -= 1                      # a[hi] is too big even with the smallest partner
    return None

def has_cycle(head) -> bool:
    slow = fast = head
    while fast and fast.next:            # fast jumps two nodes: both must exist
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            return True
    return False

def dedupe_sorted(a: list[int]) -> int:
    write = 0
    for read in range(len(a)):
        if read == 0 or a[read] != a[read - 1]:
            a[write] = a[read]
            write += 1
    return write                         # a[:write] holds the unique values
